    public static int nkIsInline(int kind) {
        // 1 for the kinds that live inside a block's text: text, span, link,
        // ref, linebreak, initial (SPEC 3.2). A `break` is a milestone, not an
        // inline.
        if (kind == nkText()) {
            return 1;
        }
        if (kind == nkSpan()) {
            return 1;
        }
        if (kind == nkLink()) {
            return 1;
        }
        if (kind == nkRef()) {
            return 1;
        }
        if (kind == nkLinebreak()) {
            return 1;
        }
        if (kind == nkInitial()) {
            return 1;
        }
        return 0;
    }
    public static int nodeIsInline(emon.Port.Cells nodes, int n) {
        // 1 when node n is an inline: an inline KIND, or a `break` with an inline neighbour (D134). A page
        // milestone INSIDE a paragraph (text, break, text) is an inline -- written in `inlines`, in order,
        // with no `id` -- and BETWEEN two blocks it is a block, as `nk-is-inline` of its kind says.
        int kind = nget(nodes, n, 0);
        int pv = nget(nodes, n, 5);
        int nx = nget(nodes, n, 4);
        if (nkIsInline(kind) == 1) {
            return 1;
        }
        if (kind == nkBreak()) {
            if (pv >= 0) {
                int pkind = nget(nodes, pv, 0);
                if (nkIsInline(pkind) == 1) {
                    return 1;
                }
            }
            if (nx >= 0) {
                int nkind = nget(nodes, nx, 0);
                if (nkIsInline(nkind) == 1) {
                    return 1;
                }
            }
        }
        return 0;
    }
    public static int nodeChildCount(emon.Port.Cells nodes, int n) {
        int c = nget(nodes, n, 2);
        int k = 0;
        while (c >= 0) {
            k += 1;
            c = nget(nodes, c, 4);
        }
        return k;
    }
    public static int nodeDepth(emon.Port.Cells nodes, int n) {
        // Edges from the node to its root: the root is 0.
        int p = nget(nodes, n, 1);
        int d = 0;
        while (p >= 0) {
            d += 1;
            p = nget(nodes, p, 1);
        }
        return d;
    }
    public static int nodeNew(emon.Port.Cells nodes, int kind, int parent) {
        // Append a node as the LAST child of `parent` (-1: a new root) and
        // answer its index, or -1 when `parent` is not a node, the kind is
        // unknown, or the node would nest deeper than `max-depth`. A new
        // node has no text, no regions, no attributes, `src` 0, `conf` -1
        // (absent), `flags` 0, `sub` 0, `aux` 0.
        int n = emon.Port.cellsLen(nodes) / 16;
        int last = -1;
        if ((kind < 1) || (kind > 26)) {
            return -1;
        }
        if (parent < -1) {
            return -1;
        }
        if (parent >= n) {
            return -1;
        }
        if (parent >= 0) {
            if (nodeDepth(nodes, parent) >= (maxDepth() - 1)) {
                return -1;
            }
            last = nget(nodes, parent, 3);
        }
        emon.Port.cellsPush(nodes, kind);
        emon.Port.cellsPush(nodes, parent);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, last);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, 0);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, 0);
        emon.Port.cellsPush(nodes, 0);
        emon.Port.cellsPush(nodes, -1);
        emon.Port.cellsPush(nodes, 0);
        emon.Port.cellsPush(nodes, 0);
        emon.Port.cellsPush(nodes, 0);
        if (parent >= 0) {
            if (last < 0) {
                nput(nodes, parent, 2, n);
            } else {
                nput(nodes, last, 4, n);
            }
            nput(nodes, parent, 3, n);
        }
        return n;
    }
    public static int modelInit(emon.Port.Cells nodes, emon.Port.Cells attrs, emon.Port.Cells regions, emon.Port.Cells text, emon.Port.Cells pages, emon.Port.Cells ledger, emon.Port.Cells layout) {
        // Empty all seven arenas and create the `document` root, node 0.
        emon.Port.cellsDrop(nodes, 0);
        emon.Port.cellsDrop(attrs, 0);
        emon.Port.cellsDrop(regions, 0);
        emon.Port.cellsDrop(text, 0);
        emon.Port.cellsDrop(pages, 0);
        emon.Port.cellsDrop(ledger, 0);
        emon.Port.cellsDrop(layout, 0);
        nodeNew(nodes, nkDocument(), -1);
        return 0;
    }
